/** 계약 포맷 `{"errors":{"<field>":["<message>"]}}`으로 직렬화되는 예외. */
export class ApiError extends Error {
  constructor(
    readonly statusCode: number,
    readonly errors: Record<string, string[]>,
  ) {
    super(`ApiError(${statusCode})`);
    this.name = 'ApiError';
  }

  /** 401 — 인증 헤더 누락 또는 토큰 무효. */
  static tokenMissing(): ApiError {
    return new ApiError(401, { token: ['is missing'] });
  }

  /** 401 — 로그인 실패(사용자 열거 방지를 위해 원인 불문 동일 응답). */
  static invalidCredentials(): ApiError {
    return new ApiError(401, { credentials: ['invalid'] });
  }

  /** 403 — 타인 리소스 수정/삭제 시도. */
  static forbidden(resource: string): ApiError {
    return new ApiError(403, { [resource]: ['forbidden'] });
  }

  /** 404 — 리소스 없음. */
  static notFound(resource: string): ApiError {
    return new ApiError(404, { [resource]: ['not found'] });
  }

  /** 409 — 유니크 충돌. */
  static conflict(field: string): ApiError {
    return new ApiError(409, { [field]: ['has already been taken'] });
  }

  /** 422 — 필수 필드 누락/빈값. */
  static blank(field: string): ApiError {
    return new ApiError(422, { [field]: ["can't be blank"] });
  }

  /** 422 — 임의의 검증 실패. */
  static unprocessable(errors: Record<string, string[]>): ApiError {
    return new ApiError(422, errors);
  }
}

