import type { ProfileDto } from '../types.js';
import { toProfile } from './profile.js';

/** Prisma에서 include로 모두 로드한 글 레코드. 시리얼라이저는 DB에 접근하지 않는다. */
export type ArticleWithRelations = {
  slug: string;
  title: string;
  description: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: { username: string; bio: string | null; image: string | null };
  tags: { order: number; tag: { name: string } }[];
  _count: { favorites: number };
  /** viewer가 좋아요했으면 길이 1, 아니면 0. 익명이면 빈 배열. */
  favorites: unknown[];
  /** viewer가 저자를 팔로우하면 길이 1. 익명이면 빈 배열. */
  authorFollowedBy: unknown[];
};

export type ArticleDto = {
  slug: string;
  title: string;
  description: string;
  body: string;
  tagList: string[];
  createdAt: string;
  updatedAt: string;
  favorited: boolean;
  favoritesCount: number;
  author: ProfileDto;
};

export function toArticle(a: ArticleWithRelations): ArticleDto {
  // tagList는 입력 순서를 보존한다(알파벳 정렬 금지).
  const tagList = [...a.tags].sort((x, y) => x.order - y.order).map((t) => t.tag.name);
  return {
    slug: a.slug,
    title: a.title,
    description: a.description,
    body: a.body,
    tagList,
    createdAt: a.createdAt.toISOString(),
    updatedAt: a.updatedAt.toISOString(),
    favorited: a.favorites.length > 0,
    favoritesCount: a._count.favorites,
    author: toProfile(a.author, a.authorFollowedBy.length > 0),
  };
}

/** 목록 응답 전용. `body` 키가 남아 있으면 hurl의 `not exists` 검증이 깨진다. */
export function toArticleSummary(a: ArticleWithRelations): Omit<ArticleDto, 'body'> {
  const { body: _omit, ...rest } = toArticle(a);
  return rest;
}

export function toArticleResponse(a: ArticleWithRelations): { article: ArticleDto } {
  return { article: toArticle(a) };
}

export function toArticlesResponse(
  items: ArticleWithRelations[],
  articlesCount: number,
): { articles: Omit<ArticleDto, 'body'>[]; articlesCount: number } {
  return { articles: items.map(toArticleSummary), articlesCount };
}

