import { ApiError } from './errors.js';

export type Dict = Record<string, unknown>;

/** 요청 바디에서 최상위 래퍼 객체(`user`, `article`, `comment`)를 꺼낸다. */
export function unwrap(body: unknown, key: string): Dict {
  if (typeof body !== 'object' || body === null) return {};
  const inner = (body as Dict)[key];
  if (typeof inner !== 'object' || inner === null) return {};
  return inner as Dict;
}

/** 키가 존재하고 비어 있지 않은 문자열이어야 한다. 아니면 422 blank. */
export function requireString(src: Dict, field: string): string {
  const value = src[field];
  if (typeof value !== 'string' || value.trim() === '') throw ApiError.blank(field);
  return value;
}

/**
 * 선택 필드. 키가 없으면 undefined, 있으면 비어 있지 않은 문자열이어야 한다.
 * `null`/`""`도 422 blank로 거부한다(username·email·password용).
 */
export function optionalRequiredString(src: Dict, field: string): string | undefined {
  if (!Object.hasOwn(src, field)) return undefined;
  return requireString(src, field);
}

/**
 * bio/image용 nullable 필드. 키가 없으면 undefined(변경 없음),
 * `null`이나 `""`은 null로 정규화한다.
 */
export function nullableString(src: Dict, field: string): string | null | undefined {
  if (!Object.hasOwn(src, field)) return undefined;
  const value = src[field];
  if (value === null || value === '') return null;
  if (typeof value !== 'string') throw ApiError.blank(field);
  return value;
}

const PASSWORD_MIN_LENGTH = 8;

/** NIST SP 800-63B: 최소 8자, 상한 없음, 문자 조합 규칙 없음. */
export function validatePassword(password: string): string {
  if (password.length < PASSWORD_MIN_LENGTH) {
    throw ApiError.unprocessable({
      password: [`is too short (minimum is ${PASSWORD_MIN_LENGTH} characters)`],
    });
  }
  return password;
}

/**
 * tagList: 키가 없으면 undefined(기존 유지), `[]`이면 전체 삭제,
 * `null`이나 비문자열 배열이면 422.
 */
export function parseTagList(src: Dict): string[] | undefined {
  if (!Object.hasOwn(src, 'tagList')) return undefined;
  const value = src.tagList;
  if (!Array.isArray(value) || value.some((t) => typeof t !== 'string')) {
    throw ApiError.unprocessable({ tagList: ['is invalid'] });
  }
  return value as string[];
}

/** 쿼리 문자열의 양의 정수 파라미터. 파싱 실패 시 기본값. */
export function parseIntParam(value: unknown, fallback: number): number {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) return fallback;
  return n;
}

