import { randomBytes } from 'node:crypto';

/**
 * 제목을 URL 안전한 slug로 변환하고 짧은 랜덤 접미사를 붙인다.
 * 동일 제목의 글 2건이 서로 다른 slug로 각각 생성되어야 하기 때문이다.
 */
export function slugify(title: string): string {
  const base = title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 80);
  const suffix = randomBytes(4).toString('hex');
  return base ? `${base}-${suffix}` : suffix;
}

