import type { FastifyPluginAsync } from 'fastify';
import { optionalAuth, requireAuth } from '../auth/hooks.js';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { toProfile, toProfileResponse } from '../serializers/index.js';
import type { ViewerId } from '../types.js';

type UsernameParams = { username: string };

async function findUserOr404(username: string) {
  const user = await prisma.user.findUnique({ where: { username } });
  if (!user) throw ApiError.notFound('profile');
  return user;
}

async function isFollowing(viewerId: ViewerId, followedId: number): Promise<boolean> {
  if (viewerId === null) return false;
  const follow = await prisma.follow.findUnique({
    where: { followerId_followedId: { followerId: viewerId, followedId } },
  });
  return follow !== null;
}

export const profilesRoutes: FastifyPluginAsync = async (app) => {
  app.get<{ Params: UsernameParams }>(
    '/profiles/:username',
    { preHandler: optionalAuth },
    async (req) => {
      const user = await findUserOr404(req.params.username);
      return toProfileResponse(toProfile(user, await isFollowing(req.userId, user.id)));
    },
  );

  app.post<{ Params: UsernameParams }>(
    '/profiles/:username/follow',
    { preHandler: requireAuth },
    async (req) => {
      const target = await findUserOr404(req.params.username);
      // 자기 자신은 팔로우하지 않으며, 중복 호출도 200으로 멱등 처리한다.
      if (target.id !== req.userId) {
        await prisma.follow.upsert({
          where: { followerId_followedId: { followerId: req.userId!, followedId: target.id } },
          create: { followerId: req.userId!, followedId: target.id },
          update: {},
        });
      }
      return toProfileResponse(toProfile(target, target.id !== req.userId));
    },
  );

  app.delete<{ Params: UsernameParams }>(
    '/profiles/:username/follow',
    { preHandler: requireAuth },
    async (req) => {
      const target = await findUserOr404(req.params.username);
      await prisma.follow.deleteMany({
        where: { followerId: req.userId!, followedId: target.id },
      });
      return toProfileResponse(toProfile(target, false));
    },
  );
};

