import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import type { ArticleWithRelations } from '../serializers/index.js';
import type { ViewerId } from '../types.js';

/**
 * 익명 뷰어를 위한 sentinel. 존재할 수 없는 id를 조건으로 걸면
 * favorites/followers 관계가 빈 배열로 로드되어 분기 없이 false가 계산된다.
 */
const NO_VIEWER = -1;

/** 글 조회에 필요한 관계를 한 번에 로드하는 include 절(N+1 방지). */
export function articleInclude(viewerId: ViewerId) {
  const id = viewerId ?? NO_VIEWER;
  return {
    author: { include: { followers: { where: { followerId: id } } } },
    tags: { include: { tag: true } },
    _count: { select: { favorites: true } },
    favorites: { where: { userId: id } },
  } as const;
}

type LoadedArticle = {
  author: { username: string; bio: string | null; image: string | null; followers: unknown[] };
  tags: { order: number; tag: { name: string } }[];
  _count: { favorites: number };
  favorites: unknown[];
  slug: string;
  title: string;
  description: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
};

/** Prisma의 중첩 관계를 시리얼라이저가 기대하는 평평한 형태로 옮긴다. */
export function shapeArticle(a: LoadedArticle): ArticleWithRelations {
  return { ...a, authorFollowedBy: a.author.followers };
}

/** 댓글 조회용 include. */
export function commentInclude(viewerId: ViewerId) {
  return {
    author: { include: { followers: { where: { followerId: viewerId ?? NO_VIEWER } } } },
  } as const;
}

export function shapeComment<
  T extends { author: { username: string; bio: string | null; image: string | null; followers: unknown[] } },
>(c: T) {
  return { ...c, authorFollowedBy: c.author.followers };
}

/** slug로 글을 찾고 없으면 404를 던진다. */
export async function findArticleOr404(slug: string, viewerId: ViewerId) {
  const article = await prisma.article.findUnique({
    where: { slug },
    include: articleInclude(viewerId),
  });
  if (!article) throw ApiError.notFound('article');
  return article;
}

/**
 * 태그 이름 배열을 Tag 레코드로 보장한 뒤 글에 순서대로 연결한다.
 * `order` 컬럼으로 입력 순서를 보존한다.
 */
export async function syncTags(articleId: number, tagList: string[]): Promise<void> {
  await prisma.articleTag.deleteMany({ where: { articleId } });
  // 중복 태그는 조인 테이블의 복합 PK와 충돌하므로 먼저 제거한다.
  const unique = [...new Set(tagList.filter((t) => t.trim() !== ''))];
  for (const [order, name] of unique.entries()) {
    const tag = await prisma.tag.upsert({ where: { name }, create: { name }, update: {} });
    await prisma.articleTag.create({ data: { articleId, tagId: tag.id, order } });
  }
}

