import type { FastifyPluginAsync } from 'fastify';
import type { Prisma } from '@prisma/client';
import { optionalAuth, requireAuth } from '../auth/hooks.js';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { toArticleResponse, toArticlesResponse } from '../serializers/index.js';
import {
  articleInclude,
  findArticleOr404,
  shapeArticle,
  syncTags,
} from '../services/articles.js';
import { slugify } from '../services/slug.js';
import { parseIntParam, parseTagList, requireString, unwrap } from '../validation.js';

type SlugParams = { slug: string };
type ListQuery = {
  tag?: string;
  author?: string;
  favorited?: string;
  limit?: string;
  offset?: string;
};

// 같은 밀리초에 생성된 글의 순서가 흔들리지 않도록 id로 안정 정렬한다.
const LIST_ORDER: Prisma.ArticleOrderByWithRelationInput[] = [
  { createdAt: 'desc' },
  { id: 'desc' },
];

export const articlesRoutes: FastifyPluginAsync = async (app) => {
  // `/articles/feed`는 `/articles/:slug`보다 먼저 등록해야 slug로 먹히지 않는다.
  app.get<{ Querystring: ListQuery }>(
    '/articles/feed',
    { preHandler: requireAuth },
    async (req) => {
      const limit = parseIntParam(req.query.limit, 20);
      const offset = parseIntParam(req.query.offset, 0);
      const where: Prisma.ArticleWhereInput = {
        author: { followers: { some: { followerId: req.userId! } } },
      };

      const [items, count] = await Promise.all([
        prisma.article.findMany({
          where,
          include: articleInclude(req.userId),
          orderBy: LIST_ORDER,
          skip: offset,
          take: limit,
        }),
        prisma.article.count({ where }),
      ]);
      return toArticlesResponse(items.map(shapeArticle), count);
    },
  );

  app.get<{ Querystring: ListQuery }>('/articles', { preHandler: optionalAuth }, async (req) => {
    const limit = parseIntParam(req.query.limit, 20);
    const offset = parseIntParam(req.query.offset, 0);
    // 필터가 여러 개면 AND로 결합한다.
    const where: Prisma.ArticleWhereInput = {
      ...(req.query.tag && { tags: { some: { tag: { name: req.query.tag } } } }),
      ...(req.query.author && { author: { username: req.query.author } }),
      ...(req.query.favorited && {
        favorites: { some: { user: { username: req.query.favorited } } },
      }),
    };

    const [items, count] = await Promise.all([
      prisma.article.findMany({
        where,
        include: articleInclude(req.userId),
        orderBy: LIST_ORDER,
        skip: offset,
        take: limit,
      }),
      // articlesCount는 페이지네이션 적용 전 필터링된 전체 개수다.
      prisma.article.count({ where }),
    ]);
    return toArticlesResponse(items.map(shapeArticle), count);
  });

  app.get<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: optionalAuth },
    async (req) => {
      const article = await findArticleOr404(req.params.slug, req.userId);
      return toArticleResponse(shapeArticle(article));
    },
  );

  app.post('/articles', { preHandler: requireAuth }, async (req, reply) => {
    const input = unwrap(req.body, 'article');
    const title = requireString(input, 'title');
    const description = requireString(input, 'description');
    const body = requireString(input, 'body');
    const tagList = parseTagList(input) ?? [];

    const created = await prisma.article.create({
      data: { slug: slugify(title), title, description, body, authorId: req.userId! },
    });
    await syncTags(created.id, tagList);

    const article = await prisma.article.findUniqueOrThrow({
      where: { id: created.id },
      include: articleInclude(req.userId),
    });
    return reply.code(201).send(toArticleResponse(shapeArticle(article)));
  });

  app.put<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: requireAuth },
    async (req) => {
      // 검사 순서: 존재(404) → 소유권(403) → 형식(422). 부분 쓰기가 없어야 한다.
      const existing = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!existing) throw ApiError.notFound('article');
      if (existing.authorId !== req.userId) throw ApiError.forbidden('article');

      const input = unwrap(req.body, 'article');
      const title = Object.hasOwn(input, 'title') ? requireString(input, 'title') : undefined;
      const description = Object.hasOwn(input, 'description')
        ? requireString(input, 'description')
        : undefined;
      const body = Object.hasOwn(input, 'body') ? requireString(input, 'body') : undefined;
      const tagList = parseTagList(input);

      // title이 바뀌어도 slug는 유지한다. updatedAt은 반드시 이전 값과 달라야 하므로
      // 태그만 바뀌는 경우에도 명시적으로 갱신한다.
      await prisma.article.update({
        where: { id: existing.id },
        data: {
          ...(title !== undefined && { title }),
          ...(description !== undefined && { description }),
          ...(body !== undefined && { body }),
          updatedAt: new Date(),
        },
      });
      if (tagList !== undefined) await syncTags(existing.id, tagList);

      const article = await prisma.article.findUniqueOrThrow({
        where: { id: existing.id },
        include: articleInclude(req.userId),
      });
      return toArticleResponse(shapeArticle(article));
    },
  );

  app.delete<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: requireAuth },
    async (req, reply) => {
      const existing = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!existing) throw ApiError.notFound('article');
      if (existing.authorId !== req.userId) throw ApiError.forbidden('article');

      await prisma.article.delete({ where: { id: existing.id } });
      return reply.code(204).send();
    },
  );
};

