import { requireAuth } from '../auth/hooks.js';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { toArticleResponse } from '../serializers/index.js';
import { articleInclude, shapeArticle } from '../services/articles.js';

type SlugParams = { slug: string };

/**
 * Favorite 테이블만 조작한다. Article 레코드를 건드리면 updatedAt이 갱신되어
 * "favorite은 updatedAt을 바꾸지 않는다"는 계약이 깨진다.
 */
async function reloadArticle(id: number, viewerId: number) {
  const article = await prisma.article.findUniqueOrThrow({
    where: { id },
    include: articleInclude(viewerId),
  });
  return toArticleResponse(shapeArticle(article));
}

export const favoritesRoutes: FastifyPluginAsync = async (app) => {
  app.post<{ Params: SlugParams }>(
    '/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (req) => {
      const article = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!article) throw ApiError.notFound('article');

      // 중복 호출도 200이어야 하므로 upsert로 멱등하게 처리한다.
      await prisma.favorite.upsert({
        where: { userId_articleId: { userId: req.userId!, articleId: article.id } },
        create: { userId: req.userId!, articleId: article.id },
        update: {},
      });
      return reloadArticle(article.id, req.userId!);
    },
  );

  app.delete<{ Params: SlugParams }>(
    '/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (req) => {
      const article = await prisma.article.findUnique({ where: { slug: req.params.slug } });
      if (!article) throw ApiError.notFound('article');

      await prisma.favorite.deleteMany({ where: { userId: req.userId!, articleId: article.id } });
      return reloadArticle(article.id, req.userId!);
    },
  );
};

