import type { FastifyPluginAsync } from 'fastify';
import { optionalAuth, requireAuth } from '../auth/hooks.js';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { toCommentResponse, toCommentsResponse } from '../serializers/index.js';
import { commentInclude, shapeComment } from '../services/articles.js';
import { requireString, unwrap } from '../validation.js';

type SlugParams = { slug: string };
type CommentParams = { slug: string; id: string };

async function findArticleIdOr404(slug: string): Promise<number> {
  const article = await prisma.article.findUnique({ where: { slug }, select: { id: true } });
  if (!article) throw ApiError.notFound('article');
  return article.id;
}

export const commentsRoutes: FastifyPluginAsync = async (app) => {
  app.post<{ Params: SlugParams }>(
    '/articles/:slug/comments',
    { preHandler: requireAuth },
    async (req, reply) => {
      const articleId = await findArticleIdOr404(req.params.slug);
      const body = requireString(unwrap(req.body, 'comment'), 'body');

      const created = await prisma.comment.create({
        data: { body, articleId, authorId: req.userId! },
        include: commentInclude(req.userId),
      });
      return reply.code(201).send(toCommentResponse(shapeComment(created)));
    },
  );

  app.get<{ Params: SlugParams }>(
    '/articles/:slug/comments',
    { preHandler: optionalAuth },
    async (req) => {
      const articleId = await findArticleIdOr404(req.params.slug);
      const comments = await prisma.comment.findMany({
        where: { articleId },
        include: commentInclude(req.userId),
        orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
      });
      return toCommentsResponse(comments.map(shapeComment));
    },
  );

  app.delete<{ Params: CommentParams }>(
    '/articles/:slug/comments/:id',
    { preHandler: requireAuth },
    async (req, reply) => {
      await findArticleIdOr404(req.params.slug);
      const id = Number(req.params.id);
      if (!Number.isInteger(id)) throw ApiError.notFound('comment');

      // 존재 검사(404)가 소유권 검사(403)보다 먼저다.
      const comment = await prisma.comment.findUnique({ where: { id } });
      if (!comment) throw ApiError.notFound('comment');
      if (comment.authorId !== req.userId) throw ApiError.forbidden('comment');

      await prisma.comment.delete({ where: { id } });
      return reply.code(204).send();
    },
  );
};

